387	/* Like cos but constrained to [-pi, +pi] */
388	static GLfloat
389	cos1 (GLfloat th)
390	{
391	  if (th < -M_PI) th = -M_PI;
392	  if (th >  M_PI) th =  M_PI;
393	  return cos (th);
394	}
