/* Shim replacement for xscreensaver's utils/easing.h. Not derived from
 * xscreensaver code.
 *
 * Only the functions a ported hack has asked for exist: a hack that names
 * another (EASE_IN_QUAD, ...) fails to compile, which is the cue to add it. */
#ifndef XSHIM_EASING_H
#define XSHIM_EASING_H

#ifdef __cplusplus
extern "C" {
#endif

typedef enum {
  EASE_NONE,
  EASE_IN_SINE,
  EASE_OUT_SINE,
  EASE_IN_OUT_SINE
} easing_function;

/* Maps x in [0, 1] to [0, 1] along the curve. x is not clamped: the sine
 * curves carry on past the ends, as upstream's do. */
double ease(easing_function, double x);

#ifdef __cplusplus
}
#endif

#endif

/* Shim replacement for xscreensaver's utils/doubletime.h. Not derived from
 * xscreensaver code. */
#ifndef XSHIM_DOUBLETIME_H
#define XSHIM_DOUBLETIME_H

#ifdef __cplusplus
extern "C" {
#endif

/* Seconds since the epoch, to the microsecond. The device has no clock set,
 * so there it counts from boot; hacks only ever subtract two readings. */
double double_time(void);

#ifdef __cplusplus
}
#endif

#endif

#include "easing.h"

#include <math.h>
#include <stdlib.h>

/* The sines run in single precision: the S3's FPU is single-precision only,
 * so a double cos is a software routine, and a hack calls this for every row
 * of every frame. */
#define PI_F 3.14159265358979323846f

double ease(easing_function fn, double x) {
  float t = (float)x;
  switch (fn) {
    case EASE_NONE:
      return x;
    case EASE_IN_SINE:
      return 1.0f - cosf(t * PI_F / 2.0f);
    case EASE_OUT_SINE:
      return sinf(t * PI_F / 2.0f);
    case EASE_IN_OUT_SINE:
      return -(cosf(PI_F * t) - 1.0f) / 2.0f;
  }
  abort();
}

#include "doubletime.h"

#include <sys/time.h>

double double_time(void) {
  struct timeval now;
  gettimeofday(&now, NULL);
  return (double)now.tv_sec + (double)now.tv_usec * 0.000001;
}

