  glVertex3f(-0.7f, top, depth);
  glVertex3f(-0.7f, top - 0.4f, depth - 0.4f * tilt);
  glVertex3f(0.7f, top, depth);
  glVertex3f(0.7f, top - 0.4f, depth - 0.4f * tilt);
